import React, {
  createContext,
  useContext,
  useState,
  type Dispatch,
  type SetStateAction,
} from 'react';

export const SelectedDataConnectionsContext = createContext<SelectedDataConnectionsContextType>({
  selectedDataConnections: {},
  setSelectedDataConnections: () => {},
});

export const useSelectedDataConnections = () => {
  return useContext(SelectedDataConnectionsContext);
};

export type SelectedDataConnectionsContextType = {
  selectedDataConnections: { [key: string]: boolean };
  setSelectedDataConnections: Dispatch<SetStateAction<{ [key: string]: boolean }>>;
};

export const SelectedDataConnectionsProvider = ({ children }: { children: React.ReactNode }) => {
  const [selectedDataConnections, setSelectedDataConnections] = useState<{
    [key: string]: boolean;
  }>({});

  return (
    <SelectedDataConnectionsContext.Provider
      value={{ selectedDataConnections, setSelectedDataConnections }}
    >
      {children}
    </SelectedDataConnectionsContext.Provider>
  );
};
