import { EhrUser } from '@getvim-os/types';
import { AlignEnum, Text, SizeToggle, Tooltip } from '@getvim/atomic-ui';
import React, { FC, useCallback } from 'react';
import { Team, useFeatureFlag } from '@getvim/feature-flags-react';
import UserIcon from '../../assets/user.svg';
import { isEmpty } from 'lodash-es';
import { HeaderBreadCrumbs } from './header-bread-crumbs/HeaderBreadCrumbs';
import { ApplicationSize } from '@getvim/vim-os-api';
import { useUserManagementSize } from '@/hub/components/UserManagementSizeContext';
import { useDevTools } from '@/hub/providers/DevToolsProvider';
import redHelpIcon from '@/atomic/assets/red-help.svg';
interface ManagementHeaderProps {
  user?: EhrUser;
  showUserInfo?: boolean;
  onUserInfoClick?: () => void;
  onClickBackToList?: () => void;
  onBackToApp?: () => void;
}

export const ManagementHeader: FC<ManagementHeaderProps> = ({
  user,
  showUserInfo,
  onUserInfoClick,
  onClickBackToList,
  onBackToApp,
}) => {
  const { currentSize, setSize, isFixedSize } = useUserManagementSize();
  const { canShowDevTools, toggleDevTools } = useDevTools();
  const name = `${user?.firstName} ${user?.lastName}`;
  const noRole = isEmpty(user?.roles);

  const [isSizeToggleEnabled] = useFeatureFlag({
    flagName: 'enableUserCenterSizeToggle',
    namespace: '',
    defaultValue: false,
    team: Team.VimOs,
  });

  const handleSizeChange = useCallback(
    (size: ApplicationSize) => {
      setSize(size);
    },
    [setSize],
  );

  return (
    <div className="flex flex-col">
      <header
        className="management-header-container bg-[#d9ebf1] h-[40px] min-h-[25px] p-[8px_16px] flex items-center text-[#011428] text-[14px]"
        role="banner"
      >
        <div className="management-header-left flex-1 flex items-center gap-[8px] text-[14px]">
          <HeaderBreadCrumbs
            showUserInfo={showUserInfo}
            onClickBackToList={onClickBackToList}
            onBackToApp={onBackToApp}
            toggleUserInfo={onUserInfoClick}
          />
        </div>
        <div className="management-header-right flex gap-[10px]">
          {canShowDevTools && (
            <Tooltip tooltipContent="Dev Tools">
              <div
                onClick={toggleDevTools}
                className="cursor-pointer flex items-center w-full h-full"
              >
                <img src={redHelpIcon} alt="Help" width={15} height={15} />
              </div>
            </Tooltip>
          )}
          {isSizeToggleEnabled && !isFixedSize && (
            <SizeToggle<ApplicationSize>
              currentSize={currentSize}
              onSizeChange={handleSizeChange}
              availableSizes={[ApplicationSize.EXTRA_LARGE, ApplicationSize.LARGE]}
            />
          )}
          <div
            data-testid="user-profile-info"
            className="account-info-button flex items-center gap-[8px] p-[4px] relative cursor-pointer rounded-[4px] hover:bg-[#01709b26]"
            onClick={onUserInfoClick}
            role="button"
            tabIndex={0}
            aria-label="User profile"
            aria-expanded={showUserInfo}
            aria-haspopup="dialog"
          >
            {noRole && (
              <div
                className="no-role-dot h-[8px] w-[8px] rounded-full bg-[#e02062] absolute left-[14px] top-[4px]"
                aria-label="User has no assigned roles"
                role="status"
              />
            )}
            <img
              src={UserIcon}
              alt="Profile icon"
              aria-hidden="true"
              className="-mt-0.5 w-[15px] h-[15px]"
            />
            <Text text={name} align={AlignEnum.left} />
          </div>
        </div>
      </header>
    </div>
  );
};
