import React, { createContext, useContext, useState, useCallback, ReactNode } from 'react';
import { useIsEmbeddedPanelView } from '../hooks/store/hub/useIsEmbeddedPanelView';
import { ApplicationSize } from '@getvim/vim-os-api';

interface UserManagementSizeContextType {
  currentSize: ApplicationSize;
  setSize: (size: ApplicationSize) => void;
  isFixedSize: boolean;
}

const UserManagementSizeContext = createContext<UserManagementSizeContextType | undefined>(
  undefined,
);

interface UserManagementSizeProviderProps {
  children: ReactNode;
  initialSize?: ApplicationSize;
}

export const UserManagementSizeProvider: React.FC<UserManagementSizeProviderProps> = ({
  children,
}) => {
  const isEmbeddedPanelView = useIsEmbeddedPanelView();
  const [currentSize, setCurrentSize] = useState<ApplicationSize>(
    isEmbeddedPanelView ? 'LARGE' : 'EXTRA_LARGE',
  );

  const setSize = useCallback((size: ApplicationSize) => {
    setCurrentSize(size);
  }, []);

  const value: UserManagementSizeContextType = {
    currentSize,
    setSize,
    isFixedSize: isEmbeddedPanelView,
  };

  return (
    <UserManagementSizeContext.Provider value={value}>
      {children}
    </UserManagementSizeContext.Provider>
  );
};

export const useUserManagementSize = (): UserManagementSizeContextType => {
  const context = useContext(UserManagementSizeContext);
  if (context === undefined) {
    throw new Error('useUserManagementSize must be used within a UserManagementSizeProvider');
  }
  return context;
};
