import React, { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';
import { MarketPlaceApplication } from '@/internal-api/marketplace-applications/marketplaceApplicationTypes';
import { useMarketPlaceApplications } from '@/hub/hooks/useMarketplaceApplication';

interface SelectedApplicationContextType {
  selectedApp?: MarketPlaceApplication;
  setSelectedAppId: React.Dispatch<React.SetStateAction<string | undefined>>;
  clearSelected: () => void;
  saveAppRequest: (id: string) => void;
  savedRequestApps: { [key: string]: boolean };
}

export const useSelectedApplicationContext = () => useContext(SelectedApplicationContext);

export const SelectedApplicationContext = createContext<SelectedApplicationContextType>({
  selectedApp: undefined,
  setSelectedAppId: () => {},
  clearSelected: () => {},
  saveAppRequest: () => {},
  savedRequestApps: {},
});

export const SelectedApplicationProvider: React.FC = ({ children }) => {
  const { apps } = useMarketPlaceApplications();
  const [selectedAppId, setSelectedAppId] = useState<string | undefined>(undefined);
  const [savedRequestApps, setSavedRequestApps] = useState<{ [key: string]: boolean }>({});
  const clearSelected = useCallback(() => {
    setSelectedAppId(undefined);
  }, []);

  useEffect(() => {
    const savedRequestAppsRaw: string | null = localStorage.getItem('marketplace-savedRequestApps');
    const parsed = savedRequestAppsRaw ? JSON.parse(savedRequestAppsRaw) : {};
    setSavedRequestApps(parsed);
  }, []);

  /** Update local storage with the app id that the user has requested to add, so it won't be possible to request it again
   * TODO: Rename to `persistAppRequestSent`
   */
  const saveAppRequest = useCallback(
    (id: string) => {
      const newSavedRequestApps = { ...savedRequestApps, [id]: true };
      setSavedRequestApps(newSavedRequestApps);
      localStorage.setItem('marketplace-savedRequestApps', JSON.stringify(newSavedRequestApps));
    },
    [savedRequestApps],
  );

  const theSelectedApp = useMemo(() => {
    if (!selectedAppId) return undefined;
    return apps?.find((app) => app.id === selectedAppId);
  }, [selectedAppId, apps]);

  return (
    <SelectedApplicationContext.Provider
      value={{
        selectedApp: theSelectedApp,
        setSelectedAppId,
        clearSelected,
        saveAppRequest,
        savedRequestApps,
      }}
    >
      {children}
    </SelectedApplicationContext.Provider>
  );
};
