import React, { useContext } from 'react';
import { AlignEnum, Text, WeightEnum } from '@getvim/atomic-ui';
import BackIcon from '../../../assets/back.svg';
import { MarketplaceCurrentPageContext } from '@/atomic/atoms/marketplace-current-page/MarketplaceCurrentPageProvider';
import { useCanSeeFullMarketplace } from '@/hub/hooks/useCanSeeFullMarketplace';
import {
  USER_CENTER_TOOLTIP,
  USER_CENTER_TOOLTIP_MARKETPLACE_OFF,
} from '@/hub/components/user-management-metadata';

interface HeaderBreadCrumbsProps {
  onClickBackToList?: () => void;
  showUserInfo?: boolean;
  onBackToApp?: () => void;
  toggleUserInfo?: () => void;
}
export const HeaderBreadCrumbs = ({
  onClickBackToList,
  showUserInfo,
  onBackToApp,
  toggleUserInfo,
}: HeaderBreadCrumbsProps) => {
  const { breadCrumbs } = useContext(MarketplaceCurrentPageContext);
  const { canSeeFullMarketplace } = useCanSeeFullMarketplace();

  const marketplaceMainBreadcrumb = canSeeFullMarketplace
    ? USER_CENTER_TOOLTIP
    : USER_CENTER_TOOLTIP_MARKETPLACE_OFF;
  const showBackButtonOnly = showUserInfo;
  if (showBackButtonOnly) {
    return (
      <div
        className="flex items-center cursor-pointer account-info"
        onClick={toggleUserInfo}
        role="button"
        tabIndex={0}
      >
        <img src={BackIcon} className="w-[10px] h-[10px] inline-block mr-1 -mt-0.5" />
        <Text text="Back" align={AlignEnum.left} weight={WeightEnum.bold} className="underline" />
      </div>
    );
  }

  const showBreadCrumbs = !showUserInfo && breadCrumbs?.length;
  if (showBreadCrumbs) {
    return (
      <div className="selected-app-info flex account-info">
        <div className="flex items-center gap-2">
          <Text
            onClick={onClickBackToList}
            className="cursor-pointer underline"
            weight={WeightEnum.bold}
            text="Back to all apps"
            align={AlignEnum.left}
            role="button"
            tabIndex={0}
          />
          {(breadCrumbs || []).map((crumb) => (
            <>
              <Text text="/" />
              <Text
                className={crumb.backToApp ? 'cursor-pointer underline' : ''}
                underline={crumb.underline}
                text={crumb.text}
                align={AlignEnum.left}
                weight={crumb.backToApp ? WeightEnum.bold : WeightEnum.normal}
                onClick={crumb.backToApp ? onBackToApp : undefined}
                role="button"
                tabIndex={0}
              />
            </>
          ))}
        </div>
      </div>
    );
  }

  // Show `User Center` text
  return (
    <div className="account-info">
      <Text text={marketplaceMainBreadcrumb} align={AlignEnum.left} weight={WeightEnum.bold} />
    </div>
  );
};
