import React, { useCallback, useContext, useMemo } from 'react';
import { useFormContext } from 'react-hook-form';
import type { RequestApplicationForm } from '@/atomic/organisms/apps-listings/request-details/requestApplicationFormType';
import { useSelectedApplicationContext } from '@/atomic/organisms/apps-listings/SelectedApplicationContext';
import { useSelectedDataConnections } from '@/atomic/organisms/apps-listings/SelectedDataConnectionsContext';

export type MarketplacePage =
  | 'LISTINGS'
  | 'DETAILS'
  | 'SECURITY'
  | 'FILL_REQUEST'
  | 'ASSIGN_TO_USERS'
  | 'SPECIFIC_ASSIGN_TO_USERS'
  | 'DATA_CONNECTIONS'
  | 'LOADER'
  | 'ERROR'
  | 'NO_APP_ERROR'
  | 'MANAGE_USERS';

interface HeaderBreadCrumbs {
  text: string;
  underline: boolean;
  backToApp: boolean;
}

interface MarketplaceRouter {
  currentPage: MarketplacePage;
  goTo: (page: MarketplacePage) => void;
  currentMarketplacePage: MarketplacePage;
  breadCrumbs?: HeaderBreadCrumbs[];
}

export const useMarketplaceCurrentPage = () => {
  return useContext(MarketplaceCurrentPageContext);
};

export const MarketplaceCurrentPageContext = React.createContext<MarketplaceRouter>({
  currentPage: 'LISTINGS',
  goTo: () => {},
  currentMarketplacePage: 'LISTINGS',
  breadCrumbs: [],
});

export const MarketplaceCurrentPageProvider: React.FC = ({ children }) => {
  const [currentPage, setCurrentPage] = React.useState<MarketplacePage>('LISTINGS');
  const { selectedApp } = useSelectedApplicationContext();
  const { selectedDataConnections, setSelectedDataConnections } = useSelectedDataConnections();
  const { reset } = useFormContext<RequestApplicationForm>();

  const onReset = useCallback(() => {
    if (Object.keys(selectedDataConnections).length > 0) {
      setSelectedDataConnections({});
    }
    reset();
  }, [selectedDataConnections, reset, setSelectedDataConnections]);

  const breadCrumbs = useMemo(() => {
    const backToAppBreadCrumb: HeaderBreadCrumbs = {
      text: selectedApp?.name || '',
      underline: false,
      backToApp: false,
    };

    switch (currentPage) {
      case 'DETAILS':
        onReset();
        return [backToAppBreadCrumb];

      case 'SECURITY':
        return [
          {
            ...backToAppBreadCrumb,
            underline: true,
            backToApp: true,
          },
          {
            text: 'Review app permissions',
            underline: false,
            backToApp: false,
          },
        ];

      case 'DATA_CONNECTIONS':
        return [
          {
            ...backToAppBreadCrumb,
            underline: true,
            backToApp: true,
          },
          {
            text: 'Select data connections',
            underline: false,
            backToApp: false,
          },
        ];

      case 'FILL_REQUEST':
        return [
          {
            ...backToAppBreadCrumb,
            underline: true,
            backToApp: true,
          },
          {
            text: 'Fill request details',
            underline: false,
            backToApp: false,
          },
        ];

      case 'ASSIGN_TO_USERS':
        return [
          {
            ...backToAppBreadCrumb,
            underline: true,
            backToApp: true,
          },
          {
            text: 'Assign to users',
            underline: false,
            backToApp: false,
          },
        ];

      case 'SPECIFIC_ASSIGN_TO_USERS':
        return [
          {
            ...backToAppBreadCrumb,
            underline: true,
            backToApp: true,
          },
          {
            text: 'Select users to assign',
            underline: false,
            backToApp: false,
          },
        ];

      case 'NO_APP_ERROR':
        return [
          {
            text: 'No access',
            underline: false,
            backToApp: false,
          },
        ];
      case 'MANAGE_USERS':
        return [
          {
            ...backToAppBreadCrumb,
            underline: true,
            backToApp: true,
          },
          {
            text: 'Select users to assign',
            underline: false,
            backToApp: false,
          },
        ];

      default:
        onReset();
        return [];
    }
  }, [currentPage, selectedApp?.name, onReset]);

  const goTo = useCallback((page: MarketplacePage) => {
    setCurrentPage(page);
  }, []);

  return (
    <MarketplaceCurrentPageContext.Provider
      value={{
        currentPage,
        goTo,
        breadCrumbs,
        currentMarketplacePage: currentPage,
      }}
    >
      {children}
    </MarketplaceCurrentPageContext.Provider>
  );
};
