import React, { createContext, useContext, useState } from 'react';
import { isLowerEnv } from '@/utils/isLowerEnv';
const isDevOrLocal = isLowerEnv();

interface DevToolsContextType {
  isDevToolsOpen?: boolean;
  toggleDevTools?: () => void;
  canShowDevTools?: boolean;
  setDevToolsOpen?: (isOpen: boolean) => void;
}

export const DevToolsContext = createContext<DevToolsContextType>({
  isDevToolsOpen: undefined,
  toggleDevTools: undefined,
  canShowDevTools: false,
  setDevToolsOpen: undefined,
});

export const DevToolsProvider = ({ children }: { children: React.ReactNode }) => {
  const [isDevToolsOpen, setIsDevToolsOpen] = useState(false);
  const toggleDevTools = () => {
    if (isDevOrLocal) {
      setIsDevToolsOpen(!isDevToolsOpen);
    }
  };

  const setDevToolsOpen = (isOpen: boolean) => {
    if (isDevOrLocal) {
      setIsDevToolsOpen(isOpen);
    }
  };
  return (
    <DevToolsContext.Provider
      value={{ isDevToolsOpen, toggleDevTools, canShowDevTools: isDevOrLocal, setDevToolsOpen }}
    >
      {children}
    </DevToolsContext.Provider>
  );
};

export const useDevTools = () => {
  return useContext(DevToolsContext);
};

// only import ReactQueryDevtoolsPanel in dev or local

export const ReactDevToolWrapper = React.lazy(() =>
  import('@tanstack/react-query-devtools/build/lib/index.prod.js').then((d) => ({
    default: d.ReactQueryDevtoolsPanel,
  })),
);
