import { useInjection } from 'inversify-react';
import { InternalApi } from '@/internal-api';
import { useQuery } from '@tanstack/react-query';

export const useCanSeeFullMarketplace = () => {
  const api = useInjection(InternalApi);

  const { isLoading, data: canSeeFullMarketplace } = useQuery({
    queryKey: ['canSeeFullMarketplace'],
    queryFn: () => api.marketPlaceApplicationsAPI.canAccessMarketPlace(),
  });

  return {
    canSeeFullMarketplace: Boolean(canSeeFullMarketplace),
    isLoadingCanSeeFullMarketplace: isLoading,
  };
};
